window.STORY_CHAPTERS["c031f96a47f434186"]={"id":"c031f96a47f434186","lines":[{"uid":"talk.rushin_2101_new_year_1#originalText","id":"talk.rushin_2101_new_year_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"祝大家新年快乐！","en":"Happy New Years, everyone!","ja":"みんな、あけましておめでとう!"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_2#originalText","id":"talk.rushin_2101_new_year_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"事不宜迟！现在就为大家介绍一下新年各种各样的活动吧～","en":"It's a bit sudden, but I have a couple of things to show you for the New Year!","ja":"さっそくだけど、お正月のアレコレについていろいろ紹介するわよ〜"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_3#originalText","id":"talk.rushin_2101_new_year_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我和学长会在「招募」中出现！","en":"Me and Kirito are going to be in a scout!","ja":"私と先輩が「スカウト」に出てるんです!"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_4#originalText","id":"talk.rushin_2101_new_year_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"而且桐人学长的插图还是由abec老师所绘制的！","en":"Plus, that picture of Kirito was drawn by abec-sensei!","ja":"それに、キリト先輩の絵はあのabec先生が描いてくださったんです!"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_5#originalText","id":"talk.rushin_2101_new_year_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好像还有各个属性保证★4的招募。","en":"Looks like there'll also be elemental ★4 guaranteed scouts!","ja":"属性別の★4確定、というのもあるみたいです"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_6#originalText","id":"talk.rushin_2101_new_year_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"还不只这些！","en":"And there's more!","ja":"それだけじゃありません!"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_7#originalText","id":"talk.rushin_2101_new_year_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你拿到新年登录奖励了吗？","en":"Did you also get the New Year login bonus?","ja":"お正月のログインボーナスはちゃんと受けとってくれた?"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_8#originalText","id":"talk.rushin_2101_new_year_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"听、听说也会推出我的特别服装喔。","en":"I-I think my special outfit will be there.","ja":"わ、私の特別衣装が出てるらしいわよ"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_9#originalText","id":"talk.rushin_2101_new_year_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"也有每天免费招募！","en":"There'll also be a free daily character scout!","ja":"毎日無料スカウトもやってるよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2101_new_year_10#originalText","id":"talk.rushin_2101_new_year_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"2021年也请继续支持Rising Steel喔！","en":"We can't wait to see you in 2021 too!","ja":"2021年も、アリブレをよろしく!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_1#originalText","id":"talk.rushin_2102_600million_1_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"终于突破600万下载！！感谢各位～！！","en":"We've finally reached six million downloads! Thanks everyone!","ja":"遂に600万ダウンロード突破!!みんなありがと〜!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_2#originalText","id":"talk.rushin_2102_600million_1_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"为了报答各位一直以来对我们的支持，到3月为止，每天都是庆典哦！！","en":"To show our thanks, we'll be celebrating every day until March!","ja":"感謝の気持ちを込めて3月まで、毎日お祭りよ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_3#originalText","id":"talk.rushin_2102_600million_1_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"锵～！！星期一到星期五每天都会举行免费招募！！","en":"First, we're doing free scouts every weekday!","ja":"じゃーん!!月曜〜金曜は毎日、無料スカウトやるわよ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_4#originalText","id":"talk.rushin_2102_600million_1_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"咦？你问星期六和星期天有没有？","en":"\"But Eydis, what about the weekends?! WEEKdays are not EVERY day!\", you say?","ja":"え? 土曜日と日曜日はないのかって?"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_5#originalText","id":"talk.rushin_2102_600million_1_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呵呵呵……","en":"Heh, heh...","ja":"ふふふ……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_6#originalText","id":"talk.rushin_2102_600million_1_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你放心吧。我们会在这个星期内再公开新情报的。","en":"Fear not. We've got more info on that coming later on this week!","ja":"安心して。みんなに喜んでもらえるように催し物はたっくさん準備してるわ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_7#originalText","id":"talk.rushin_2102_600million_1_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我们还在企划其他各式各样的活动！为了能让大家乐在其中，准备了很多活动呢。","en":"We're in the middle of planning out all sorts of good stuff!","ja":"2月12日の「ウィークエンドSAOゲームス」の生配信でまた新しい情報が公開されるそうよ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_1_8#originalText","id":"talk.rushin_2102_600million_1_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"所以！就好好期待这一次的活动吧！","en":"You just gotta wait a teeeeny tiiiiiny bit longer for it, okay?","ja":"だからもうちょっと、期待して待っててね!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_1#originalText","id":"talk.rushin_2102_600million_2_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"告诉你关于感谢祭的2项追加情报哦。","en":"I've got two announcements about our ongoing SIXGIVING event!","ja":"感謝祭の追加情報を2つお知らせするわね"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_2#originalText","id":"talk.rushin_2102_600million_2_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"首先第1项！除了周一到周五的免费招募……","en":"First! In addition to our free scouts happening Monday through Friday, we've got...","ja":"まずは1つ目!月曜日から金曜日の無料スカウトに加えて……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_3#originalText","id":"talk.rushin_2102_600million_2_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"每周星期六和星期天也会举行最多110连抽的免费招募～！！","en":"Saturday and Sunday scouts where you can scout up to 110 times, for free!","ja":"毎週土曜日と日曜日はなんと最大110連無料スカウトを実施しまーす!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_4#originalText","id":"talk.rushin_2102_600million_2_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"第2项的新情报是……","en":"Big announcement number two is...","ja":"2つ目の新情報は……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_5#originalText","id":"talk.rushin_2102_600million_2_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"2月14日起举行的「庆祝情人节特选招募」！！","en":"A Valentine's pick up scout starting on, you guessed it, Valentine's day, February 14th!","ja":"2月14日から「バレンタイン記念ピックアップスカウト」を開催!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_6#originalText","id":"talk.rushin_2102_600million_2_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"详细内容记得要注意公告喔！","en":"Check out the notice for more info!","ja":"3回限定、step3で★4キャラが1体以上確定さらに★4の的中率は通常のスカウトの2倍!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_7#originalText","id":"talk.rushin_2102_600million_2_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么可能会这么优惠，真是难以置信……！！","en":"Cause it's a really good deal!","ja":"まったくなんてお得なのかしら……!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_8#originalText","id":"talk.rushin_2102_600million_2_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"各位请务必用自己的双眼亲自确认一下哦。","en":"And you're not going to want to miss it!","ja":"ぜひその眼で確認してみてね"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_2_9#originalText","id":"talk.rushin_2102_600million_2_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今后也会继续追加企划！耐心等待我们的消息吧！","en":"The SIXGIVING fun isn't over yet. So stay tuned for more announcements coming soon!","ja":"催しは今後もどんどん追加するわよ!続報待っててね!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_3_1#originalText","id":"talk.rushin_2102_600million_3_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"告诉你关于感谢祭的第3弹追加情报哦。","en":"Hey there! You ready for another SIXGIVING announcement? Well, here comes number three!","ja":"感謝祭の追加情報、第3弾をお知らせするわね"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_3_2#originalText","id":"talk.rushin_2102_600million_3_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"2月21日起将会开始举行「庆祝600万下载登录奖励」！！","en":"Starting from 2/21 we're doing a SIXGIVING login bonus!","ja":"2月21日から「600万DL記念ログインボーナス」を開始!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_3_3#originalText","id":"talk.rushin_2102_600million_3_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"可以获得总共250个的钻石晶体、","en":"We're giving out up to 250 diamond cubes! But that's not all...","ja":"合計250個のダイヤ・キューブや"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_3_4#originalText","id":"talk.rushin_2102_600million_3_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"保证★4武器招募券及保证★4角色招募券！！","en":"You can also get a ★4 Weapon Guaranteed Scout Ticket AND a ★4 Character Guaranteed Scout Ticket!","ja":"★4武器確定スカウトチケットと★4キャラ確定スカウトチケットももらえるの!!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_3_5#originalText","id":"talk.rushin_2102_600million_3_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"千万要记得将全部的奖励拿到手哦！！","en":"So set up an alarm or do whatever you gotta do to make sure you don't miss anything!","ja":"ちゃんと忘れず全部手に入れてね!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_3_6#originalText","id":"talk.rushin_2102_600million_3_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那先这样，耐心等待我们的消息吧！","en":"Pretty exciting stuff, right? Stay tuned for more info coming your way soon!","ja":"それじゃまた、続報待っててね!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_1#originalText","id":"talk.rushin_2102_600million_4_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"大家在感谢祭还玩得开心吗？接下来要一次把剩下的情报全部告诉你们哦！","en":"Liking our SIXGIVING extravaganza? I got one more big update for you!","ja":"みんな感謝祭楽しんでる?残りの情報を、一気に全部お伝えするわよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_2#originalText","id":"talk.rushin_2102_600million_4_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"首先是「奖励任务」！！","en":"Kicking things off, we've got bonus quests!","ja":"まずは「ボーナスクエスト」!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_3#originalText","id":"talk.rushin_2102_600million_4_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"2月28日起至3月7日为止，每天都会解放一个不同的特别任务。","en":"From February 28th to March 7th, there'll be a special quest unlocked every day!","ja":"2月28日から3月7日まで毎日1つずつ特別なクエストが解放されていくわ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_4#originalText","id":"talk.rushin_2102_600million_4_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"通过全部的奖励任务就可以获得各属性的解放结晶各100个及全能解放结晶100个，总计800个哦！！","en":"Clear 'em all to get 100 evolution crystals per element (including almighty)! That's 800 crystals!","ja":"全部クリアすると、各属性の解放結晶が100個ずつと全能の解放結晶が100個、合計で800個も手に入るのよ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_5#originalText","id":"talk.rushin_2102_600million_4_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"接着是「登录奖励轮盘」！！","en":"Next up, we've got the login bonus roulette!","ja":"次に、「ログインボーナスルーレット」!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_6#originalText","id":"talk.rushin_2102_600million_4_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"2月28日起至3月7日为止，每天都可以获得招募券哦。","en":"From February 28th to March 7th, you can get a scout ticket every day!","ja":"2月28日から3月7日まで毎日スカウトチケットがもらえるわ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_7#originalText","id":"talk.rushin_2102_600million_4_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"有不同种类的票券，其中也有可以进行保证★4角色招募的票券，详情请在公告中确认。","en":"Keep a lookout on ticket types! There's even one that guarantees a ★4 character! ","ja":"チケットには種類があって、★4キャラが確定でスカウトできるものもあるから、お知らせで詳細を確認してね"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_8#originalText","id":"talk.rushin_2102_600million_4_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"可以使用那张票券的招募将在3月7日公开，敬请期待！","en":"The scout for this ticket will be available on March 7th! Yippie!","ja":"そのチケットが使えるスカウトは3月7日に公開されるから楽しみにしてて!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_9#originalText","id":"talk.rushin_2102_600million_4_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"最后是「想像力超强化」！！","en":"Lastly, we've got super-charged imaginarium!","ja":"最後に、「イマジネーション超強化」!!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_10#originalText","id":"talk.rushin_2102_600million_4_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好像……有几个人被超强化了耶！到底是谁啊……我也来确认一下公告好了！","en":"Looks like a couple of enhanced folks! I wonder who it could be...I'll have to go check... ","ja":"何人か、超強化された人がいるらしいわよ!誰かしら……あたしもお知らせ見てみよう"},"kind":"dialogue"},{"uid":"talk.rushin_2102_600million_4_11#originalText","id":"talk.rushin_2102_600million_4_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"感谢祭之后，3月7日当日还有其他好消息等着你哦。敬请期待吧！","en":"After SIXGIVING, we've got more news ready on March 7! Stay tuned for more!","ja":"感謝祭のあと、3月7日にまた素敵な発表があるから期待して待っててね!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_0#originalText","id":"talk.rushin_2102_short_novel_8_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"恋爱中的少女们 vol.1 『诗乃的练等』","en":"Maidens in Love, vol. 1: Sinon's Leveling","ja":"恋する少女たち vol.1 『シノンのレベリング』"},"kind":"caption"},{"uid":"talk.rushin_2102_short_novel_8_1#originalText","id":"talk.rushin_2102_short_novel_8_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真不愧是诗乃，妳已经不会输给普通的无名怪物了吧。","en":"Wow, Sinon, normal mob monsters can't even touch you anymore.","ja":"さすがシノン、もう普通のモブモンスターには負けることはないな"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_2#originalText","id":"talk.rushin_2102_short_novel_8_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我的确是越来越熟悉射箭时的手感了。跟《GGO》里的狙击也差不了多少。","en":"Yeah, I'm finally used to the bow. It's pretty similar to shooting in GGO.","ja":"確かに、弓を撃つ感覚には慣れてきたわ《GGO》の狙撃と、そんなに変わらないし"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_3#originalText","id":"talk.rushin_2102_short_novel_8_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是吗……？我觉得看起来差很多耶。","en":"You think so? Looks completely different to me.","ja":"そうか……?全然違うように見えるけど"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_4#originalText","id":"talk.rushin_2102_short_novel_8_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"但我还是不太习惯空中飞行，真亏大家有办法在那种风速下飞呢。","en":"Flying still scares me, though. I don't know how the others do it.","ja":"やっぱり、空を飛ぶっていうのはまだ慣れないわみんな、よくあんな風に飛べるわね"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_5#originalText","id":"talk.rushin_2102_short_novel_8_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我一开始也吃了不少苦头喔。不过，习惯后就能飞得像走路一样自然啰。","en":"I struggled at first, too. But it'll be as easy as walking once you get used to it.","ja":"最初は俺も、ずいぶん苦労したよでも慣れれば、歩くのと同じように飛べると思うぜ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_6#originalText","id":"talk.rushin_2102_short_novel_8_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就跟学游泳还有骑自行车差不多啦。","en":"It's like learning to swim or ride a bike.","ja":"水泳や自転車と変わらないよ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_7#originalText","id":"talk.rushin_2102_short_novel_8_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"哦……这样啊……那我认真练练看好了。","en":"Hmm...really? Okay, I guess I'll give it another honest try.","ja":"ふーん、そう……それじゃ、少し本腰を入れてやってみようかな"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_8#originalText","id":"talk.rushin_2102_short_novel_8_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这样的话，我来陪妳练习吧。","en":"I'll help.","ja":"だったら俺も付き合うよ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_8_9#originalText","id":"talk.rushin_2102_short_novel_8_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"真是谢啦，那我就恭敬不如从命啰。","en":"Really? Well...thanks. I'll take you up on that.","ja":"ありがとそれじゃお言葉に甘えちゃおうかな"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_0#originalText","id":"talk.rushin_2102_short_novel_9_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"恋爱中的少女们 vol.2 『西莉卡的约会大作战！』","en":"Maidens in Love, vol. 2: Silica's Date Plan!","ja":"恋する少女たち vol.2 『シリカのデート大作戦!』"},"kind":"caption"},{"uid":"talk.rushin_2102_short_novel_9_1#originalText","id":"talk.rushin_2102_short_novel_9_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"毕娜，抱歉了。今天就麻烦你乖乖待在家里一下唷。","en":"Sorry, Pina. You'll have to be home alone for a bit today.","ja":"ピナ、ごめんね今日は少しだけ、お家でおとなしくしてて"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_2#originalText","id":"talk.rushin_2102_short_novel_9_2","speaker":{"cn":"毕娜","en":"Pina","ja":"ピナ"},"text":{"cn":"啾！","en":"Skreee!","ja":"きゅるるっ!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_3#originalText","id":"talk.rushin_2102_short_novel_9_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"因为我好不容易才约到桐人哥今天一起出来……而且就只有我们两个！","en":"Yes, but I finally asked Kirito to hang out... one-on-one!","ja":"だって、今日はやっとキリトさんを誘えたんだから……しかも、ふたりっきりで!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_4#originalText","id":"talk.rushin_2102_short_novel_9_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天莉兹姊姊一整天都要工作，亚丝娜跟莉法姊姊都没有登录。","en":"Liz is at work all day, and Asuna and Leafa aren't logged in.","ja":"リズさんは今日はずっとお仕事だしアスナさんとリーファちゃんは、ログインしてこない"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_5#originalText","id":"talk.rushin_2102_short_novel_9_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我做了万全的调查，不会有错才对！","en":"I double-checked everything. This has to go my way!","ja":"しっかり調査したから、間違いないはずです!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_6#originalText","id":"talk.rushin_2102_short_novel_9_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"让妳久等了，西莉卡。","en":"Hi, Silica.","ja":"お待たせー、シリカ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_7#originalText","id":"talk.rushin_2102_short_novel_9_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"啊，桐人哥！那么，毕娜，我出门啰。","en":"Oh! Hi, Kirito! Well, Pina, don't wait up!","ja":"あっ、キリトさん!それじゃピナ、行ってきます"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_8#originalText","id":"talk.rushin_2102_short_novel_9_8","speaker":{"cn":"毕娜","en":"Pina","ja":"ピナ"},"text":{"cn":"啾──！","en":"Skreee!","ja":"きゅるるるーッ!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_9_9#originalText","id":"talk.rushin_2102_short_novel_9_9","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"嗯，我会加油的！","en":"Thanks. I will!","ja":"うん、がんばってくる!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_0#originalText","id":"talk.rushin_2102_short_novel_10_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"恋爱中的少女们 vol.3 『莉兹贝特的材料搜集』","en":"Maidens in Love, vol. 3: Lisbeth's Search for Materials","ja":"恋する少女たち vol.3 『リズベットの素材探し』"},"kind":"caption"},{"uid":"talk.rushin_2102_short_novel_10_1#originalText","id":"talk.rushin_2102_short_novel_10_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"嗯～天气真好！真是适合挖掘的好日子！","en":"Mmm, what a nice day! Just perfect for excavation!","ja":"うーん、いい天気!絶好の発掘日和ね!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_2#originalText","id":"talk.rushin_2102_short_novel_10_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"欸，莉兹，今天是要去哪里啊？妳没有找其他人来吗？","en":"Liz, where're we headed today? Is anyone else coming?","ja":"なあリズ、今日はどこへ行くんだ?ほかのメンツは誘ってないのか?"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_3#originalText","id":"talk.rushin_2102_short_novel_10_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天比较特殊，因为我想去守卫精灵领地的遗迹，而你就是守卫精灵嘛。","en":"I wanted to check out Spriggan ruins. You're a Spriggan, right?","ja":"今日はちょっとね、スプリガン領にある遺跡に行きたくてあんたスプリガンでしょ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_4#originalText","id":"talk.rushin_2102_short_novel_10_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是没错啦，但我可不熟守卫精灵领地喔，也几乎没有去过。","en":"Yeah, but I don't know Spriggan territory that well.","ja":"そうだけど、俺はスプリガン領なんて知らないぞ?ほとんど行ったこともないし"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_5#originalText","id":"talk.rushin_2102_short_novel_10_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"没关系啦！今天就我跟你两个人一起去！","en":"Never mind that! Anyway, it's just you and me on this outing!","ja":"いいから!今日はあんたとあたし、ふたりでいくの!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_6#originalText","id":"talk.rushin_2102_short_novel_10_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"明白了吗？","en":"You're cool with that, right?","ja":"いいわね!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_7#originalText","id":"talk.rushin_2102_short_novel_10_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是……","en":"Sure…","ja":"はい……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_8#originalText","id":"talk.rushin_2102_short_novel_10_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"别露出那种表情嘛。拿到目标矿物后，我也会帮你改造加强装备的。","en":"I'll give your equipment a tune-up if we find what I'm looking for.","ja":"そんな顔しないでよ目的の鉱物がとれたら、あんたの装備もチューンアップしてあげるから"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_9#originalText","id":"talk.rushin_2102_short_novel_10_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真的吗？好，那我一定要找到矿物！","en":"Really? All right then, let's go excavating!","ja":"本当か?よし、絶対見つけるぞ!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_10_10#originalText","id":"talk.rushin_2102_short_novel_10_10","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"受不了你，真是现实的家伙……呵呵。","en":"Haha... I always know how to entice you.","ja":"まったく、現金なんだから……ふふ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_0#originalText","id":"talk.rushin_2102_short_novel_11_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"恋爱中的少女们 vol.4 『在大家来之前独处的有纪与亚丝娜』","en":"Maidens in Love, vol. 4: Yuuki And Asuna, Alone Briefly","ja":"恋する少女たち vol.4 『ユウキとアスナ、みんなが来るまでふたりっきり』"},"kind":"caption"},{"uid":"talk.rushin_2102_short_novel_11_1#originalText","id":"talk.rushin_2102_short_novel_11_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嗯～大家是怎么了呢？明明说好这个时间集合的耶。","en":"Hmm, where is everyone? They said they'd be here by now.","ja":"うーん、みんなどうしたんだろうこの時間に集まるって言ってたのに"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_2#originalText","id":"talk.rushin_2102_short_novel_11_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"怎么办？我们自己先来开头目对策会议吗？","en":"Maybe we should start this boss battle strategy meeting without them?","ja":"どうしよう、先に始めちゃおうかボス対策会議"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_3#originalText","id":"talk.rushin_2102_short_novel_11_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"大家应该都有很多事情要忙吧。我们就慢慢等吧。","en":"Well, they might be busy with something, right? Let's just wait for them.","ja":"みんなだって、何かと忙しいんじゃない?ゆっくり待ちましょうよ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_4#originalText","id":"talk.rushin_2102_short_novel_11_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"可是……","en":"But…","ja":"でも……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_5#originalText","id":"talk.rushin_2102_short_novel_11_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"有纪，妳还是很顾虑我呢。妳对沉睡骑士的其他人就不会说这种话吧？","en":"Yuuki, that's not something you'd say to any of the others, right?","ja":"ユウキ、まだわたしに気を使ってるでしょスリーピング・ナイツのほかの人には、そんなこと言わないんじゃない?"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_6#originalText","id":"talk.rushin_2102_short_novel_11_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"啊……嗯，或许是吧……","en":"Ah...yeah. I guess not…","ja":"あ……うんそうかもしれない……かな"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_7#originalText","id":"talk.rushin_2102_short_novel_11_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我也已经是公会成员了，希望妳能对我一视同仁喔。","en":"I'm part of the Sleeping Knights too. You should treat me that way.","ja":"わたしだって、もうギルドのメンバーなんだからねみんなと同じようにしてほしいな"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_8#originalText","id":"talk.rushin_2102_short_novel_11_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"……我知道了，亚丝娜！那就等大家来吧！","en":"Okay, Asuna, you win! Let's wait for the others.","ja":"……わかったよ、アスナ!じゃあ、みんなを待とう!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_9#originalText","id":"talk.rushin_2102_short_novel_11_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"至于在那之前要做什么……","en":"But until they get here…","ja":"それまでは……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_10#originalText","id":"talk.rushin_2102_short_novel_11_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"没关系，就随便聊聊天吧。那样也很开心呀。","en":"We could just talk, you know? I think that'd be fun.","ja":"いいじゃない、普通におしゃべりしてればそれも楽しいでしょ?"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_11#originalText","id":"talk.rushin_2102_short_novel_11_11","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嗯！每次跟亚丝娜聊天，我都非常开心喔！","en":"Cool! I always have lots of fun talking with you, Asuna!","ja":"うん!ボク、アスナとおしゃべりするの、すっごく楽しいよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_11_12#originalText","id":"talk.rushin_2102_short_novel_11_12","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嘿嘿嘿……谢谢妳，亚丝娜。","en":"Hehe... Thanks, Asuna.","ja":"えへへ……ありがとう、アスナ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_0#originalText","id":"talk.rushin_2102_short_novel_12_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"恋爱中的少女们 vol.5 『亚丝娜的便当』","en":"Maidens in Love, vol. 5: Asuna's Bento","ja":"恋する少女たち vol.5 『アスナのお弁当』"},"kind":"caption"},{"uid":"talk.rushin_2102_short_novel_12_1#originalText","id":"talk.rushin_2102_short_novel_12_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就选这里吧？风景也不错呢。","en":"Let's stop here. It's got a great view.","ja":"このあたりにしましょうか景色もいいし"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_2#originalText","id":"talk.rushin_2102_short_novel_12_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个嘛……虽说这里不算《圈内》，不过乍看也没有怪物的踪迹。","en":"Okay... We're not \"in range,\" but I don't see any sign of monsters.","ja":"そうだな……《圏内》じゃないけど、ぱっと見モンスターの足跡もなさそうだし"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_3#originalText","id":"talk.rushin_2102_short_novel_12_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"《追踪》连这种事情都有办法知道吗？真是的，你到底拥有多少技能啊。","en":"Your \"Tracking\" skill shows you that much? Just how many skills do you have?","ja":"《追跡》ってそんなことまでわかるの?まったく、君はいくつスキルを持ってるのよ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_3_1#originalText","id":"talk.rushin_2102_short_novel_12_3_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"《追踪》连这种事情都有办法知道吗？","en":"Your \"Tracking\" skill shows you that much?","ja":"《追跡》ってそんなことまでわかるの?"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_3_2#originalText","id":"talk.rushin_2102_short_novel_12_3_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"真是的，你到底拥有多少技能啊。","en":"Just how many skills do you have?","ja":"まったく、君はいくつスキルを持ってるのよ"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_4#originalText","id":"talk.rushin_2102_short_novel_12_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那是因为我没有全力灌注在料理技能上。","en":"Well, I didn't focus excessively on cooking, unlike a certain someone.","ja":"俺は料理スキルに全力投球してないからな"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_5#originalText","id":"talk.rushin_2102_short_novel_12_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊，你竟然敢这么说。既然如此，这个便当就……","en":"Oh, if that's how you feel, I guess you don't need lunch…","ja":"あ、そういうこと言うんだだったら、このお弁当は……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_6#originalText","id":"talk.rushin_2102_short_novel_12_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"等……等一下！我非常尊敬料理技能的！","en":"W-Wait a minute! Cooking skills are awesome! Mad respect!","ja":"ちょ……ちょっとタンマ!料理スキルすごい、尊敬してます!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_7#originalText","id":"talk.rushin_2102_short_novel_12_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……真的吗？","en":"You mean it?","ja":"……ほんと?"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_8#originalText","id":"talk.rushin_2102_short_novel_12_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真的啦！毕竟还是要有美味的餐点，才让人更有干劲嘛！","en":"Of course I mean it! A tasty meal really boosts morale, too!","ja":"ほんとだって!やっぱりおいしい食事は、気合も入るし!"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_9#originalText","id":"talk.rushin_2102_short_novel_12_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你好像很慌张……不过算了。来，这是今天的便当。","en":"Now you just sound desperate, you know? Well, never mind. Here you go.","ja":"なーんか慌ててるけど……ま、いっかはい、これが今日のお弁当"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_9_1#originalText","id":"talk.rushin_2102_short_novel_12_9_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你好像很慌张……不过算了。","en":"Now you just sound desperate, you know?","ja":"なーんか慌ててるけど……ま、いっか"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_9_2#originalText","id":"talk.rushin_2102_short_novel_12_9_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"来，这是今天的便当。","en":"Well, never mind. Here you go.","ja":"はい、これが今日のお弁当"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_10#originalText","id":"talk.rushin_2102_short_novel_12_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"唔喔喔喔喔！有够豪华的……","en":"Woo hoo! You really went all out…","ja":"うおおおっ!すごく豪華だ……"},"kind":"dialogue"},{"uid":"talk.rushin_2102_short_novel_12_11#originalText","id":"talk.rushin_2102_short_novel_12_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"分量有很多，不用急，慢慢吃吧。","en":"There's plenty to eat, too, so take your time.","ja":"たくさんあるから、慌てずゆっくり食べてね"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_1#originalText","id":"talk.rushin_2103_ur_cp_1_1","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"大家还过的好吗？今天由我们为你们介绍「Unital ring特别活动」哦！","en":"Hey there! I'm here to blow your mind with some news about our Unital Ring campaign!","ja":"みんな元気? 今日はあたしたちから「ユナイタル・リングキャンペーン」を紹介するわ!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_2#originalText","id":"talk.rushin_2103_ur_cp_1_2","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"首先是从3月8日0点起开始的「登录奖励」！","en":"We're gonna start the party off with a special login bonus that starts on 3/8 at 12:00 a.m.!","ja":"まずは3月8日の0時から始まる「ログインボーナス」です!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_3#originalText","id":"talk.rushin_2103_ur_cp_1_3","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"除了总计100个的钻石晶体，还可获得解放结晶、月晶石及交换之剑！","en":"You can get evolution crystals, moon crystals, exchange swords AND up to 100 diamond cubes!","ja":"ダイヤ・キューブ合計100個の他に解放結晶や月晶石、エクスチェンジソードももらえます!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_4#originalText","id":"talk.rushin_2103_ur_cp_1_4","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"真的是好康大放送呢！","en":"Chaaaaaaaching!","ja":"まさに大盤振る舞いね!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_5#originalText","id":"talk.rushin_2103_ur_cp_1_5","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"关于「Unital ring特别交换商店」我来说明一下哦。","en":"Next, we've got a Special Unital Ring Exchange Point!","ja":"次に「ユナイタル・リング特別交換所」について説明するわね"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_6#originalText","id":"talk.rushin_2103_ur_cp_1_6","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"从3月的第2个星期起至4月下旬举行的各种活动中，收集Unital ring特别交换券的话，","en":"Starting the second week of March till the end of April, get Special Unital Ring Exchange Tickets...","ja":"3月2週目から4月下旬に開催される各イベントで「ユナイタル・リング特別交換券」を集めると"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_7#originalText","id":"talk.rushin_2103_ur_cp_1_7","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"就可以在「Unital ring特别交换商店」中交换各种报酬。","en":"And trade em at the Special Unital Ring Exchange Point for all sorts of cool stuff!","ja":"「ユナイタル・リング特別交換所」でいろんな報酬と交換できます"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_8#originalText","id":"talk.rushin_2103_ur_cp_1_8","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"我们最推荐的是穿着生还者学校制服的爱丽丝～！","en":"I recommend the Survivor School Uniform Alice.","ja":"あたしたちのイチオシはこの帰還者学校の制服を着たアリスね〜!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_9#originalText","id":"talk.rushin_2103_ur_cp_1_9","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"真的是非常适合呢！！","en":"She looks...ugh, so cute. I just can't.","ja":"とってもよく似合ってますよね!!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_10#originalText","id":"talk.rushin_2103_ur_cp_1_10","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"最后，为你们介绍有关招募的事情！","en":"Finally! Scouts! They say five scouts a day keeps the doctor away...","ja":"最後に、スカウトについて紹介するわ"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_11#originalText","id":"talk.rushin_2103_ur_cp_1_11","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"从3月8日0点起至4月底星期一～星期五每天举行「1天5次免费招募」。","en":"So we're doing an x5 a day scout! It runs every weekday starting 3/8 at midnight til late April!","ja":"3月8日の0時から4月の終わりまで月曜〜金曜は「1日5回無料スカウト」を毎日やってるわ"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_12#originalText","id":"talk.rushin_2103_ur_cp_1_12","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"星期六和星期天是「免费11连抽招募」！！","en":"We've also got 11x scouts going on during the weekend!","ja":"土曜と日曜は、「11連スカウト」です!!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_13#originalText","id":"talk.rushin_2103_ur_cp_1_13","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"此外，本次特别活动最受注目的地方就是「Unital ring特别招募」！！","en":"The featured scout is Special Character  Scout: Unital Ring!","ja":"さらに、このキャンペーンの目玉である「ユナイタル・リング特別スカウト」に注目!!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_14#originalText","id":"talk.rushin_2103_ur_cp_1_14","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"登录ALO的爱丽丝将在限定期间中于招募登场！！","en":"This one's got ALO Alice, so you're gonna wanna get her before she's gone!","ja":"ALOにログインしたアリスが期間限定でスカウトに登場!!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_15#originalText","id":"talk.rushin_2103_ur_cp_1_15","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"种族和我相同，是猫妖！","en":"Just like ya girl here, her race is a Cait Sith!","ja":"種族はあたしと同じ、ケットシーです"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_16#originalText","id":"talk.rushin_2103_ur_cp_1_16","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"好像也收录了一些特别的语音哦～","en":"There's some special Japanese voice lines in there for ya, too!","ja":"いくつかボイスも特別に収録したみたいですよ"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_17#originalText","id":"talk.rushin_2103_ur_cp_1_17","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"跟期间限定也有点关系总觉得提起劲了呢～","en":"She's only going to be available for a limited time, so make sure you got your cubes ready!","ja":"期間限定ってこともあってなんだか気合入ってるわね〜"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_18#originalText","id":"talk.rushin_2103_ur_cp_1_18","speaker":{"cn":"珪子","en":"Keiko"},"text":{"cn":"你问说是第1弹，那就会有第2弹啰？","en":"Did you notice the name says part 1? Wonder if there's a part 2..."},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_19#originalText","id":"talk.rushin_2103_ur_cp_1_19","speaker":{"cn":"里香","en":"Rika"},"text":{"cn":"嘻嘻，现在先保密！","en":"I guess we'll just have to wait and find out!"},"kind":"dialogue"},{"uid":"talk.rushin_2103_ur_cp_1_20#originalText","id":"talk.rushin_2103_ur_cp_1_20","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"那么，请继续留意之后的更新！","en":"At any rate, stay tuned for more surprises coming your way!","ja":"それじゃまた、続報をお楽しみに!"},"kind":"dialogue"},{"uid":"talk.rushin_2104_final_cp_1_1#originalText","id":"talk.rushin_2104_final_cp_1_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"欢迎回来……桐人。","en":"Welcome back...Kirito.","ja":"おかえりなさい……キリト"},"kind":"dialogue"},{"uid":"talk.rushin_2104_final_cp_1_2#originalText","id":"talk.rushin_2104_final_cp_1_2","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_3#originalText","id":"talk.rushin_2104_final_cp_1_3","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_4#originalText","id":"talk.rushin_2104_final_cp_1_4","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_5#originalText","id":"talk.rushin_2104_final_cp_1_5","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_6#originalText","id":"talk.rushin_2104_final_cp_1_6","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_7#originalText","id":"talk.rushin_2104_final_cp_1_7","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_8#originalText","id":"talk.rushin_2104_final_cp_1_8","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_9#originalText","id":"talk.rushin_2104_final_cp_1_9","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_10#originalText","id":"talk.rushin_2104_final_cp_1_10","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_11#originalText","id":"talk.rushin_2104_final_cp_1_11","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_12#originalText","id":"talk.rushin_2104_final_cp_1_12","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_13#originalText","id":"talk.rushin_2104_final_cp_1_13","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_14#originalText","id":"talk.rushin_2104_final_cp_1_14","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_15#originalText","id":"talk.rushin_2104_final_cp_1_15","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_16#originalText","id":"talk.rushin_2104_final_cp_1_16","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_17#originalText","id":"talk.rushin_2104_final_cp_1_17","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_18#originalText","id":"talk.rushin_2104_final_cp_1_18","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_19#originalText","id":"talk.rushin_2104_final_cp_1_19","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2104_final_cp_1_20#originalText","id":"talk.rushin_2104_final_cp_1_20","speaker":{},"text":{"cn":"（仮）","en":"（仮）"},"kind":"narration"},{"uid":"talk.rushin_2105_campaign_1_1#originalText","id":"talk.rushin_2105_campaign_1_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"各位，谢谢你们今天也来到《Rising Steel》！","en":"Thanks again for logging on to Rising Steel!","ja":"みなさん、今日も《アリブレ》に来てくれてどうもありがとう!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_campaign_1_2#originalText","id":"talk.rushin_2105_campaign_1_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"《Rising Steel》终于要迎接1.5周年了！","en":"It's finally Rising Steel's 1.5-year anniversary!","ja":"《アリブレ》もついに1.5周年を迎えるんだ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_campaign_1_3#originalText","id":"talk.rushin_2105_campaign_1_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"将会有豪华10大特别活动，要好好确认内容哦！","en":"There's 10 huge campaigns ready, so check it out!","ja":"豪華10大キャンペーンをやるからしっかりチェックしてくれよ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_campaign_1_4#originalText","id":"talk.rushin_2105_campaign_1_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"热闹万分呢！！","en":"They're MASSIVE!","ja":"大盛りあがりね!!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_campaign_1_5#originalText","id":"talk.rushin_2105_campaign_1_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"还有更多内容！这边是从5月上旬开始！","en":"It starts in early May so you've got time!","ja":"まだまだあるぞこっちは5月上旬から始まるんだ!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_campaign_1_6#originalText","id":"talk.rushin_2105_campaign_1_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"从1.5周年起，《赛季制》要开始了呢！","en":"The season system will also start around then!","ja":"1.5周年から、《シーズン制》というのも始まるのよね"},"kind":"dialogue"},{"uid":"talk.rushin_2105_campaign_1_7#originalText","id":"talk.rushin_2105_campaign_1_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"详细内容请看公告。","en":"So read up on the notice for more info!","ja":"ああ、詳しくはお知らせを読んでくれ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_0#originalText","id":"talk.rushin_2105_short_novel_13_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.1 『桐人待过的世界』","en":"After WoU, vol. 1: The World Kirito Lived In","ja":"After WoU vol.1 『キリトのいた世界』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_13_1#originalText","id":"talk.rushin_2105_short_novel_13_1","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"桐人老师，请问老师以前待的世界是什么样子？","en":"Master Kirito, what is life like in the world you came from?","ja":"キリト先生、先生のいた世界ってどんな感じなんですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_2#originalText","id":"talk.rushin_2105_short_novel_13_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个嘛……跟这里完全不一样喔。既没有神圣术，也没有龙。","en":"Well... It's completely different from life here. There's no Sacred Arts, for one, and no dragons.","ja":"そうだなあ……こことは全然違うよ神聖術もないし、竜もいなかった"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_3#originalText","id":"talk.rushin_2105_short_novel_13_3","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"没有龙跟神圣术……那样有办法在空中飞吗？","en":"No Sacred Arts or dragons... So, that means you couldn't fly?","ja":"竜も神聖術もなし……それじゃ、空は飛べんのですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_4#originalText","id":"talk.rushin_2105_short_novel_13_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"有办法飞喔，只要运用飞机跟直升机……这类旋翼航空器就可以。","en":"Oh, we could fly. Using machines called planes and helicopters.","ja":"いや、飛べたよ飛行機とかヘリコプター……回転翼機で"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_5#originalText","id":"talk.rushin_2105_short_novel_13_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这些叫做机器的东西，是以电力或热能为动力来驱动……这样讲听得懂吗？","en":"And \"machines\" are things that move by electricity and...uh…","ja":"機械っていうんだけど、電気や熱をエネルギーにして動く……と言えばわかるかな"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_6#originalText","id":"talk.rushin_2105_short_novel_13_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"飞机的话，还可以同时载好几百个人飞上天喔。","en":"Anyway, a plane can fly with hundreds of passengers.","ja":"飛行機なら、数百人を乗せて飛ぶこともできたよ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_7#originalText","id":"talk.rushin_2105_short_novel_13_7","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"好几百人……那还真是壮观啊。我也想搭搭看。","en":"Hundreds... How efficient! I'd love to fly on one of them.","ja":"数百……それは景気がいいですなあいっぺん、オレもそれに乗ってみたいですわ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_8#originalText","id":"talk.rushin_2105_short_novel_13_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"运用神圣术的热素跟钢素的话，说不定在这个世界也行得通喔。","en":"Well, we could probably build planes here using Sacred Arts and steel.","ja":"神聖術の熱素や鋼素を使えばできるかもしれないなこっちの世界でも"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_13_9#originalText","id":"talk.rushin_2105_short_novel_13_9","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"那么，我会很期待的。请您务必制作出那种机器，桐人老师。","en":"Then I'll look forward to seeing this plane! You'll definitely build it, right, Master Kirito?","ja":"なら、楽しみにしてますぜひ作ってくださいよ、キリト先生"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_0#originalText","id":"talk.rushin_2105_short_novel_14_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.2 『伊迪丝与涅吉小子』","en":"After WoU, vol. 2: Eydis and Little Negi","ja":"After WoU vol.2 『イーディスとネギ坊』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_14_1#originalText","id":"talk.rushin_2105_short_novel_14_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"喂～涅吉小子，你知不知道桐人在哪里？","en":"Hey, Little Negi, do you know where Kirito is?","ja":"ねー、ネギ坊キリトどこにいるか知らない?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_2#originalText","id":"talk.rushin_2105_short_novel_14_2","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"我不叫涅吉！我的名字叫做涅鲁基乌斯！","en":"Hey, don't call me that! I have a proper name, Nergius!","ja":"私はネギではない!ネルギウスという名前がある!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_3#originalText","id":"talk.rushin_2105_short_novel_14_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这种小事我当然知道啊。大家都是出于亲切才叫你涅吉小子的。","en":"Oh, I know, but everyone lovingly calls you Little Negi.","ja":"知ってるわよ、それくらいみんな、親愛をこめて言ってるんだよ、ネギ坊って"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_4#originalText","id":"talk.rushin_2105_short_novel_14_4","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"我一点也不想要这种亲切感。麻烦妳好好喊我的名字好吗？伊迪丝阁下！","en":"I care not for that so-called love. I'd much rather you call me by my proper name, Lady Eydis!","ja":"そんな親愛など欲しくもないちゃんと名前で呼んでいただきたいな、イーディス殿!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_5#originalText","id":"talk.rushin_2105_short_novel_14_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"唔哇……你还是老样子有够古板的。这样子可不会受女孩子欢迎的喔～","en":"Eesh, if you keep being so stubborn, you'll never get a girlfriend…","ja":"うわー、相変わらず固いわねそんなんじゃ女の子にモテないぞー"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_6#originalText","id":"talk.rushin_2105_short_novel_14_6","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"集成骑士不需要受异性欢迎！伊迪丝阁下自己才是太过随兴了吧！","en":"That has nothing to do with our duties as Knights! I think you're a little too relaxed, Lady Eydis.","ja":"整合騎士が異性にモテる必要などない!イーディス殿こそ、少し緩みすぎではないのか"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_7#originalText","id":"talk.rushin_2105_short_novel_14_7","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"既然贵为集成骑士，应当真心诚意侍奉公理教会，维护人民安宁……","en":"Integrity Knights must serve the Axiom Church and protect…","ja":"整合騎士たる者、公理教会に誠心誠意仕え人民の安寧を……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_14_8#originalText","id":"talk.rushin_2105_short_novel_14_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊～是是是，我知道～我真是个笨蛋才会来问你。","en":"Yeah, yeah, fine. It was stupid of me to ask you in the first place.","ja":"あーはいはい、わかってますよーあんたに聞いたあたしが馬鹿だった"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_0#originalText","id":"talk.rushin_2105_short_novel_15_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.3 『亚丝娜和哈娜的料理对谈』","en":"After WoU Vol. 3: Asuna and Hana's Cooking Sermon","ja":"After WoU vol.3 『アスナとハナのお料理談義』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_15_1#originalText","id":"talk.rushin_2105_short_novel_15_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哇啊……好壮观的厨房喔！","en":"Ooh, what a nice kitchen!","ja":"うわあ、立派なお台所ね!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_2#originalText","id":"talk.rushin_2105_short_novel_15_2","speaker":{"cn":"哈娜","en":"Hana","ja":"ハナ"},"text":{"cn":"是的……不过，储备的食材都在之前的大战用光了。","en":"It is... But the war has diminished our stockpiles.","ja":"はい……ですが、先の大戦で備蓄はなくなってしまいました"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_3#originalText","id":"talk.rushin_2105_short_novel_15_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"放心吧，世界已经和平了。很快就能恢复原状了。","en":"Don't worry, now that there's peace, everything will soon be back to the way it was before.","ja":"大丈夫よ、平和になったんだからすぐに元通りになるわ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_4#originalText","id":"talk.rushin_2105_short_novel_15_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不过，这样子做不了菜呢……","en":"Though you have a point. Our cooking options are pretty slim right now.","ja":"でも、これじゃお料理は難しいわね……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_5#originalText","id":"talk.rushin_2105_short_novel_15_5","speaker":{"cn":"哈娜","en":"Hana","ja":"ハナ"},"text":{"cn":"那个……如果不介意吃简单一点，是可以就现有材料做出几道菜……","en":"If you want to cook something simple, there's a lot we can make.","ja":"あの、簡単なものでよろしければ、ここにあるものでいくつか拵えることができますが……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_6#originalText","id":"talk.rushin_2105_short_novel_15_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"真的吗！？那可以拜托妳吗？","en":"Really?! Then I'll take you up on it!","ja":"ほんと!?なら、ぜひお願いできる?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_7#originalText","id":"talk.rushin_2105_short_novel_15_7","speaker":{"cn":"哈娜","en":"Hana","ja":"ハナ"},"text":{"cn":"好的。","en":"As you wish, my lady.","ja":"かしこまりました"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_8#originalText","id":"talk.rushin_2105_short_novel_15_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"看这个……是派吧。感觉好好吃喔！我要开动了！","en":"With these... Yeah, it'll be a pie. Looking good!","ja":"これは……パイねすっごくおいしそう! いただきます!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_9#originalText","id":"talk.rushin_2105_short_novel_15_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……好吃！不只是因为刚出炉，这个蜂蜜也……","en":"It's delicious! Partly because it's freshly baked, but this honey…","ja":"……おいしい!焼きたてだからっていうのもあるけど、このハチミツが……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_10#originalText","id":"talk.rushin_2105_short_novel_15_10","speaker":{"cn":"哈娜","en":"Hana","ja":"ハナ"},"text":{"cn":"过奖了，我愧不敢当。","en":"I am humbled by your praise.","ja":"お褒めいただき恐縮です"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_15_11#originalText","id":"talk.rushin_2105_short_novel_15_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"真的很好吃喔。以后麻烦妳多多教我做菜！","en":"That really was fantastic. I'm excited to learn more from you!","ja":"本当においしかったわこれから、お料理たくさん教えてくださいね!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_0#originalText","id":"talk.rushin_2105_short_novel_16_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.4 『来自艾莉的祝贺』","en":"After WoU, vol. 4: Congratulations From Airy","ja":"After WoU vol.4 『エアリーからのお祝い』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_16_1#originalText","id":"talk.rushin_2105_short_novel_16_1","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"谢达大人，早安。","en":"Good morning, Lady Sheyta","ja":"シェータ様、おはようございます"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_2#originalText","id":"talk.rushin_2105_short_novel_16_2","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"妳是……升降盘的……","en":"You're from...the Floating Platform...","ja":"あなたは、昇降盤の……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_3#originalText","id":"talk.rushin_2105_short_novel_16_3","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"是的，代表剑士大人赋予了我新的天职，同时也帮我取了名字。","en":"Yes. The swordsman delegate gave me a new Calling. Also, a name.","ja":"はい、代表剣士様に新たな天職をいただきましたその際に、名前も付けていただきまして"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_4#originalText","id":"talk.rushin_2105_short_novel_16_4","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"是吗……那太好了。妳的名字是？","en":"Oh... Good. What's your name?","ja":"そう……よかった名前は?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_5#originalText","id":"talk.rushin_2105_short_novel_16_5","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"我叫做艾莉。","en":"Airy is my new name.","ja":"エアリー、と申します"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_6#originalText","id":"talk.rushin_2105_short_novel_16_6","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"艾莉……是个好名字。","en":"Airy... Nice name.","ja":"エアリー……いい名前"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_7#originalText","id":"talk.rushin_2105_short_novel_16_7","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"我也要恭喜谢达大人。我听说谢达大人要结婚了。","en":"I've been meaning to congratulate you on your upcoming marriage, my lady.","ja":"シェータ様も、おめでとうございますご結婚、なさると伺いました"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_8#originalText","id":"talk.rushin_2105_short_novel_16_8","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……嗯，对。结婚后，我应该会过去对方的国家。","en":"Thank you... I will probably be moving to the Dark Territory after we are wed.","ja":"……うん、そう結婚して、向こうの国に行くことになると思う"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_9#originalText","id":"talk.rushin_2105_short_novel_16_9","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"希望将来我也有机会去那里拜访您。虽说或许会有点困难……","en":"I'm hoping to travel there too. Though that may prove difficult…","ja":"いつか、私もご挨拶に行けたらと思います難しいかもしれませんが……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_10#originalText","id":"talk.rushin_2105_short_novel_16_10","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"不，一定可以的。因为那名代表剑士改变了这个世界。","en":"No, I'm sure you can do it. The delegate has changed the world.","ja":"ううん、きっと大丈夫よあの代表剣士が、世界を変えてくれたから"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_11#originalText","id":"talk.rushin_2105_short_novel_16_11","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"到时我会好好欢迎妳来的。毕竟妳帮了我很多。","en":"You can stay with us when you visit. I owe you a great deal.","ja":"その時は、ちゃんとお迎えするからあなたには、ずっとお世話になったもの"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_12#originalText","id":"talk.rushin_2105_short_novel_16_12","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"不敢当，我只是做好分内工作罢了。","en":"Please, you do not owe me anything, my lady. I was only doing my job.","ja":"とんでもございません私はただ、仕事をしただけでございます"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_16_13#originalText","id":"talk.rushin_2105_short_novel_16_13","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……即使是这样，我还是很高兴。谢谢妳的祝贺，艾莉。","en":"But you still lifted my spirits. Thank you for your good wishes, Airy.","ja":"……それでも、私は嬉しかったからお祝いしてくれてありがとう、エアリー"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_0#originalText","id":"talk.rushin_2105_short_novel_17_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.5 『连利的邀约』","en":"After WoU, vol. 5: Renly's Overture","ja":"After WoU vol.5 『レンリのお誘い』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_17_1#originalText","id":"talk.rushin_2105_short_novel_17_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……妳、妳好。","en":"H-Hi there.","ja":"……や、やあ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_2#originalText","id":"talk.rushin_2105_short_novel_17_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"啊，连利大人！您刚回来吗？","en":"Oh! Lord Renly! Have you just returned?","ja":"あっ、レンリ様!今お戻りですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_3#originalText","id":"talk.rushin_2105_short_novel_17_3","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"啊……嗯，因为那边总算也比较安定了。","en":"Yes, just now. Things have finally settled down over there.","ja":"ああ、うんやっと向こうも収まってね"},"kind":"dialogue"}]};
